"use client";

import { useEffect, useMemo, useRef, useState, useTransition } from "react";

import type { SaveResult } from "@/lib/admin/content-actions";
import { countReferencePhotos, SECTION_LABELS, sectionSummary } from "@/lib/admin/section-fields";
import type { SiteLink } from "@/lib/admin/site-links";
import type { Section } from "@/lib/content/sections";
import type { MediaItem } from "@/lib/media/library";

import { MediaLibraryProvider } from "./MediaPicker";
import { SectionFields, SiteLinksDatalist, SiteLinksProvider } from "./SectionEditor";

/**
 * The editor for a list of bands — the homepage, or any page.
 *
 * Left: the bands in order, each opening into its full form. Right: the real
 * page, reloaded after each save, at computer or phone width.
 *
 * Nothing is live until **Save**. Leaving with unsaved changes asks first.
 */

type AnySection = Section & Record<string, unknown>;

/** A fresh band id. Module scope: it is only ever called from a click. */
function newSectionId(type: string) {
  return `${type}-${Date.now().toString(36)}`;
}

function sectionName(section: Section) {
  return SECTION_LABELS[section.type]?.name ?? section.type;
}

export function SectionListEditor({
  initialSections,
  templates,
  media,
  links,
  previewPath,
  save,
  header,
  extraDirty = false,
  onSaved,
}: {
  initialSections: readonly Section[];
  /** One example of each band type, offered under "Add a band". */
  templates: readonly Section[];
  media: MediaItem[];
  links: SiteLink[];
  /** Page to show in the preview. */
  previewPath: string;
  save: (sections: readonly Section[]) => Promise<SaveResult>;
  /** Rendered above the list — page title fields and the like. */
  header?: React.ReactNode;
  /** The parent has unsaved changes of its own (title etc.). */
  extraDirty?: boolean;
  onSaved?: () => void;
}) {
  const [sections, setSections] = useState<AnySection[]>(initialSections as AnySection[]);
  const [openId, setOpenId] = useState<string | null>(null);
  const [adding, setAdding] = useState(false);
  const [dirty, setDirty] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [width, setWidth] = useState<"computer" | "phone">("computer");
  const [pending, startTransition] = useTransition();
  const preview = useRef<HTMLIFrameElement>(null);

  const unsaved = dirty || extraDirty;

  useEffect(() => {
    if (!unsaved) return;
    const warn = (event: BeforeUnloadEvent) => event.preventDefault();
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [unsaved]);

  const change = (next: AnySection[]) => {
    setSections(next);
    setDirty(true);
    setMessage(null);
  };

  const move = (index: number, delta: number) => {
    const target = index + delta;
    if (target < 0 || target >= sections.length) return;
    const next = [...sections];
    [next[index], next[target]] = [next[target]!, next[index]!];
    change(next);
  };

  const add = (template: Section) => {
    const copy = structuredClone(template) as AnySection;
    copy.id = newSectionId(template.type);
    change([...sections, copy]);
    setOpenId(copy.id);
    setAdding(false);
  };

  const referenceCount = useMemo(() => countReferencePhotos(sections), [sections]);

  const doSave = () => {
    setError(null);
    startTransition(async () => {
      const result = await save(sections);
      if (!result.ok) {
        setError(result.error);
        return;
      }
      setDirty(false);
      setMessage("Saved — the live site is showing this now.");
      onSaved?.();
      if (preview.current) preview.current.src = `${previewPath}?saved=${Date.now()}`;
    });
  };

  return (
    <MediaLibraryProvider initial={media}>
      <SiteLinksProvider value={links}>
        <SiteLinksDatalist />
        <div className="space-y-6">
          {header}

          <div
            className="sticky top-0 z-20 -mx-2 flex flex-wrap items-center justify-between gap-3 px-2 py-3"
            style={{ backgroundColor: "var(--a-surface)" }}
          >
            <div className="a-body-sm" style={{ color: "var(--a-ink-variant)" }}>
              {sections.length} bands
              {referenceCount > 0 ? (
                <span className="ml-3" style={{ color: "var(--a-status-waiting)" }}>
                  · {referenceCount} reference photo{referenceCount === 1 ? "" : "s"} to replace before launch
                </span>
              ) : null}
            </div>
            <div className="flex items-center gap-3">
              {unsaved ? (
                <span className="a-label" style={{ color: "var(--a-status-waiting)" }}>
                  Unsaved changes
                </span>
              ) : null}
              <a href={previewPath} target="_blank" rel="noreferrer" className="a-btn-secondary">
                Open page ↗
              </a>
              <button type="button" onClick={doSave} disabled={pending || !unsaved} className="a-btn-primary">
                {pending ? "Saving…" : "Save & publish"}
              </button>
            </div>
          </div>

          {error ? (
            <p role="alert" className="a-body-sm px-4 py-3" style={{ color: "var(--a-negative)", backgroundColor: "var(--a-negative-container)", borderRadius: "var(--a-radius)" }}>
              {error}
            </p>
          ) : null}
          {message ? (
            <p role="status" className="a-body-sm" style={{ color: "var(--a-status-done)" }}>
              {message}
            </p>
          ) : null}

          <div className="grid gap-8 2xl:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
            <div className="space-y-3">
              <ol className="space-y-3">
                {sections.map((section, index) => {
                  const open = openId === section.id;
                  const refs = countReferencePhotos(section);
                  return (
                    <li key={section.id} className="a-card" style={{ borderRadius: "var(--a-radius-md)" }}>
                      <div className="flex items-center gap-3 px-4 py-3">
                        <span className="a-label w-6 shrink-0 tabular-nums" style={{ color: "var(--a-outline)" }}>
                          {index + 1}
                        </span>
                        <button
                          type="button"
                          className="min-w-0 flex-1 text-left"
                          onClick={() => setOpenId(open ? null : section.id)}
                          aria-expanded={open}
                        >
                          <span className="a-body-md block truncate" style={{ color: "var(--a-ink)" }}>
                            {sectionSummary(section) || sectionName(section)}
                          </span>
                          <span className="a-label block" style={{ color: "var(--a-outline)" }}>
                            {sectionName(section)}
                            {refs > 0 ? (
                              <span style={{ color: "var(--a-status-waiting)" }}> · {refs} reference photo{refs === 1 ? "" : "s"}</span>
                            ) : null}
                          </span>
                        </button>
                        <button type="button" className="a-btn-icon" aria-label="Move up" disabled={index === 0} onClick={() => move(index, -1)}>↑</button>
                        <button type="button" className="a-btn-icon" aria-label="Move down" disabled={index === sections.length - 1} onClick={() => move(index, 1)}>↓</button>
                        <button type="button" className="a-btn-secondary" onClick={() => setOpenId(open ? null : section.id)}>
                          {open ? "Close" : "Edit"}
                        </button>
                        <button
                          type="button"
                          className="a-label px-1 underline"
                          style={{ color: "var(--a-negative)" }}
                          onClick={() => {
                            if (confirm(`Remove "${sectionSummary(section) || sectionName(section)}" from this page? You can add it back until you save.`)) {
                              change(sections.filter((other) => other.id !== section.id));
                            }
                          }}
                        >
                          Remove
                        </button>
                      </div>
                      {open ? (
                        <div className="border-t px-5 py-5" style={{ borderColor: "var(--a-outline-variant)" }}>
                          <p className="a-body-sm mb-5" style={{ color: "var(--a-outline)" }}>
                            {SECTION_LABELS[section.type]?.hint}
                          </p>
                          <SectionFields
                            section={section as never}
                            onChange={(next) =>
                              change(sections.map((other) => (other.id === section.id ? (next as unknown as AnySection) : other)))
                            }
                          />
                        </div>
                      ) : null}
                    </li>
                  );
                })}
              </ol>

              {sections.length === 0 ? (
                <p className="a-body-md py-8 text-center" style={{ color: "var(--a-outline)" }}>
                  This page has no bands yet. Add one below.
                </p>
              ) : null}

              <div>
                <button type="button" className="a-btn-accent" onClick={() => setAdding(!adding)} aria-expanded={adding}>
                  {adding ? "Close" : "+ Add a band"}
                </button>
                {adding ? (
                  <ul className="mt-4 grid gap-3 md:grid-cols-2" role="list">
                    {templates.map((template) => (
                      <li key={template.type}>
                        <button
                          type="button"
                          onClick={() => add(template)}
                          className="a-card-interactive block h-full w-full p-4 text-left"
                          style={{ borderRadius: "var(--a-radius-md)" }}
                        >
                          <span className="a-body-md block" style={{ color: "var(--a-ink)" }}>
                            {sectionName(template)}
                          </span>
                          <span className="a-body-sm mt-1 block" style={{ color: "var(--a-outline)" }}>
                            {SECTION_LABELS[template.type]?.hint} Starts as a copy of an existing one for you to change.
                          </span>
                        </button>
                      </li>
                    ))}
                  </ul>
                ) : null}
              </div>
            </div>

            <div className="hidden 2xl:block">
              <div className="sticky top-16">
                <div className="mb-2 flex items-center justify-between">
                  <p className="a-label" style={{ color: "var(--a-outline)" }}>
                    The live page — refreshes when you save
                  </p>
                  <div className="flex gap-1" role="group" aria-label="Preview width">
                    {(["computer", "phone"] as const).map((option) => (
                      <button
                        key={option}
                        type="button"
                        aria-pressed={width === option}
                        className={width === option ? "a-btn-primary" : "a-btn-secondary"}
                        onClick={() => setWidth(option)}
                      >
                        {option === "computer" ? "Computer" : "Phone"}
                      </button>
                    ))}
                  </div>
                </div>
                <div
                  className="mx-auto overflow-hidden border"
                  style={{
                    width: width === "phone" ? 390 : "100%",
                    borderColor: "var(--a-outline-variant)",
                    borderRadius: "var(--a-radius-md)",
                  }}
                >
                  <iframe ref={preview} src={previewPath} title="Page preview" className="h-[78vh] w-full bg-white" />
                </div>
              </div>
            </div>
          </div>
        </div>
      </SiteLinksProvider>
    </MediaLibraryProvider>
  );
}
